import{_ as a,a as t,c as o,ac as i}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"第四册：流利英语 · Lesson 35 Space odyssey","description":"学习 将来完成时与未来截止点，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第四册：流利英语 · Lesson 35 Space odyssey","description":"学习 将来完成时与未来截止点，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第4册课时","summary":"学习 将来完成时与未来截止点，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第四册：流利英语 · Lesson 34 Adolescence","link":"/life/english/new-concept/book-4/unit-05/lesson-034"},"next":{"text":"第四册：流利英语 · Lesson 36 The cost of government","link":"/life/english/new-concept/book-4/unit-05/lesson-036"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第四册：流利英语 · Lesson 34 Adolescence","link":"/life/english/new-concept/book-4/unit-05/lesson-034"},"next":{"text":"第四册：流利英语 · Lesson 36 The cost of government","link":"/life/english/new-concept/book-4/unit-05/lesson-036"}},"headers":[],"relativePath":"life/english/new-concept/book-4/unit-05/lesson-035.md","filePath":"life/english/new-concept/book-4/unit-05/lesson-035.md"}'),n={name:"life/english/new-concept/book-4/unit-05/lesson-035.md"};function l(s,e,r,c,h,d){return t(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="第四册-流利英语-·-lesson-35-space-odyssey" tabindex="-1">第四册：流利英语 · Lesson 35 Space odyssey <a class="header-anchor" href="#第四册-流利英语-·-lesson-35-space-odyssey" aria-label="Permalink to &quot;第四册：流利英语 · Lesson 35 Space odyssey&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-4/contents">本册目录</a> · <a href="/life/english/new-concept/book-4/unit-05/overview">单元 5</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>借太空旅行的想象和工程挑战练习阅读预测性文字，区分计划、预期与已经完成的事实。历史材料中的未来时间表不能直接当作今天的任务进度。重点使用将来完成时，准确说明在某个未来节点之前预计完成的动作，并保留条件和不确定性。</p><p>本课以主题阅读带动语言分析，学习重点如下。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>mission</td><td>/ˈmɪʃən/</td><td>n.</td><td>任务</td><td>a space mission</td></tr><tr><td>orbit</td><td>/ˈɔːbɪt/</td><td>n.</td><td>轨道</td><td>enter orbit</td></tr><tr><td>trajectory</td><td>/trəˈdʒektəri/</td><td>n.</td><td>轨迹</td><td>calculate a trajectory</td></tr><tr><td>module</td><td>/ˈmɒdjuːl/</td><td>n.</td><td>舱；模块</td><td>a research module</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>by the time — 到某个时间点时</li><li>on schedule — 按计划进度</li></ul><h2 id="语法讲解-将来完成时与未来截止点" tabindex="-1">语法讲解：将来完成时与未来截止点 <a class="header-anchor" href="#语法讲解-将来完成时与未来截止点" aria-label="Permalink to &quot;语法讲解：将来完成时与未来截止点&quot;">​</a></h2><p>will have done 表示到某个未来时间点为止预计已经完成的动作，常与 by Friday、by the time…搭配。它不同于 will be doing，后者表示届时正在进行。by the time 引导未来时间从句时通常用一般现在时。计划文本中的 will have completed 是预测或承诺，并不是完成事实；若条件尚不确定，可用 may have completed 或明确加入 if 从句。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>By the time the simulated crew arrives, the support team will have checked every system.</p></blockquote><p>到模拟机组到达时，支援团队将已检查完所有系统。</p><p>arrives 为未来时间从句的一般现在时；will have checked 表该时点前完成。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>by the time the crew will arrive 不用于普通未来时间从句；应使用 arrives。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>对比读 will be checking 与 will have checked，分别重读 checking 和 checked；录音检查完成时是否漏掉 have。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>We are testing the communication system today. By noon tomorrow, we will have completed the first simulation. If a fault appears, the final rehearsal will be delayed.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>为虚构训练任务写三句进度说明：当前阶段、明日截止点、条件变化。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>明确模拟情境，把预测截止点与可能改变计划的条件分开。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>示例检查系统是在机组到达之前还是之后完成？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 之前。</p><p><strong>解析：</strong> 将来完成时以到达为截止点。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>填空：By noon tomorrow, we will have ___ the simulation.（finish）</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> finished</p><p><strong>解析：</strong> will have 后接过去分词。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>will be checking 与 will have checked 的重点有什么不同？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 前者强调届时正在检查，后者强调届时已完成。</p><p><strong>解析：</strong> 进行体与完成体的时间观察角度不同。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：将来完成时与未来截止点。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-4/unit-05/grammar">单元语法</a> · <a href="/life/english/new-concept/book-4/unit-05/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-4/unit-05/review">单元自测</a></p><p><a href="/life/english/new-concept/book-4/unit-05/lesson-034">上一课</a> · <a href="/life/english/new-concept/book-4/unit-05/overview">单元目录</a> · <a href="/life/english/new-concept/book-4/unit-05/lesson-036">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const b=a(n,[["render",l]]);export{u as __pageData,b as default};
